import React, { useState, useEffect } from 'react';
import DatePicker from 'react-datepicker';
import { useNavigate } from 'react-router-dom';
import '../css/Job.css';

function Job() {		
  	const navigate = useNavigate();
  	const [roleOptions, setRoleOptions] = useState([]);
  	const [selectedRoleOption, setSelectedRoleOption] = useState();
  	const [jobDescription, setJobDescription] = useState("");
  	const [jobResponsibilities, setJobResponsibilities] = useState("");
  	const [jobRequirements, setJobRequirements] = useState("");
  	const [locationOptions, setLocationOptions] = useState([]);
  	const [selectedLocationOption, setSelectedLocationOption] = useState();
  	const [employmentTypeOptions, setEmploymentOptions] = useState([]);
  	const [selectedEmploymentTypeOption, setSelectedEmploymentTypeOption] = useState();
  	const [experienceLevelOptions, setExpereinceLevelOptions] = useState([]);
  	const [selectedExperienceLevelOption, setSelectedExperienceLevelOption] = useState();
  	const [jobSalary, setJobSalary] = useState();
  	const [postedDate, setPostedDate] = useState();
  	const [lastDate, setLastDate] = useState(null);

  	const handleRoleOptionChange = (event) => {
    	let selectedIndex = event.target.selectedIndex - 1;
      	setSelectedRoleOption(roleOptions[selectedIndex]);
    }

    const handleJobDescriptionChange = (event) => {
      	setJobDescription(event.target.value);
    }

    const handleJobResponsibilitiesChange = (event) => {
      	setJobResponsibilities(event.target.value);
    }

    const handleJobRequirementsChange = (event) => {
      	setJobRequirements(event.target.value);
    }

    const handleLocationOptionChange = (event) => {
      	let selectedIndex = event.target.selectedIndex - 1;
      	setSelectedLocationOption(locationOptions[selectedIndex]);
    }

    const handleEmploymentTypeOptionChange = (event) => {
      	let selectedIndex = event.target.selectedIndex - 1;
      	setSelectedEmploymentTypeOption(employmentTypeOptions[selectedIndex]);
    }

    const handleExperienceLevelOptionChange = (event) => {
      	let selectedIndex = event.target.selectedIndex - 1;
      	setSelectedExperienceLevelOption(experienceLevelOptions[selectedIndex]);
    }

    const handleJobSalaryChange = (event) => {
      	setJobSalary(event.target.value);
    }

    const handleLastDateChange = (date) => {
      	console.log('>>> selected date is ' + date);
        setLastDate(date);
    }
  	return(
    	<div className="job-form-container">
            <p className="form-title">Create New Job</p>

            <select value={selectedRoleOption} onChange={handleRoleOptionChange}>
                <option value="">Select Role</option>
                {roleOptions.map((option, index) => (
                    <option key={index} value={option.value}>{option.label}</option>
                ))}
            </select>

            <input
                type="text"
                onChange={handleJobDescriptionChange}
                placeholder="Enter Job Description"
            />

            <input
                type="text"
                onChange={handleJobResponsibilitiesChange}
                placeholder="Enter Job Responsibilities"
            />

            <input
                type="text"
                onChange={handleJobRequirementsChange}
                placeholder="Enter Job Requirements"
            />

            <select value={selectedLocationOption} onChange={handleLocationOptionChange}>
                <option value="">Select Location</option>
                {locationOptions.map((option, index) => (
                    <option key={index} value={option.value}>{option.label}</option>
                ))}
            </select>

            <select value={selectedEmploymentTypeOption} onChange={handleEmploymentTypeOptionChange}>
                <option value="">Select Employment Type</option>
                {employmentTypeOptions.map((option, index) => (
                    <option key={index} value={option.value}>{option.label}</option>
                ))}
            </select>

            <select value={selectedExperienceLevelOption} onChange={handleExperienceLevelOptionChange}>
                <option value="">Select Required Experience Level</option>
                {experienceLevelOptions.map((option, index) => (
                    <option key={index} value={option.value}>{option.label}</option>
                ))}
            </select>

            <input
                type="number"
                onChange={handleJobSalaryChange}
                placeholder="Enter Salary in LPA"
            />

            <div className="datepicker-wrapper">
                <DatePicker
                    className="custom-datepicker-input"
                    selected={lastDate}
                    onChange={handleLastDateChange}
                    dateFormat="dd/MM/yyyy"
                    showYearDropdown
                    scrollableMonthYearDropdown
                    placeholderText="Select Last Date to Apply"
                />
            </div>
        </div>



    )
}

export default Job;
